private fun scheduleStartup(epoch: ServiceEpoch, delayMs: Long) {
if (!isEpochCurrent(epoch)) return
try {
synchronized(epoch) {
val future = startupExecutor.schedule({
// A zero-delay task must not reschedule before its future has been installed.
synchronized(epoch) { if (!isEpochCurrent(epoch)) return@schedule }
val caller = Thread.currentThread()
epoch.startupCaller.set(caller)
try { if (isEpochCurrent(epoch)) ensureEngine(epoch) }
catch (t: Throwable) {
if (isEpochCurrent(epoch)) {
epoch.startupQueued.set(false)
Log.e("dsh-engine", "service startup failed", t)
}
}
finally { epoch.startupCaller.compareAndSet(caller, null) }
}, delayMs, TimeUnit.MILLISECONDS)
epoch.startupFuture.getAndSet(future)?.cancel(false)
if (!isEpochCurrent(epoch)) future.cancel(true)
}
} catch (_: java.util.concurrent.RejectedExecutionException) {
// Destruction can reject a queued retry. No effects or replacement teardown follow.
}
}

fun finish(filesDir: File, delete: (File) -> Unit = { SnapshotFs.deletePath(it) }) {
// 0.14.1 块K ②（反馈二）：产物清理**不得**阻止 marker 清除。marker 是恢复权威；
// 它一旦残留 SWAPPED，之后每次启动都会重跑 roll-forward，而 .snapshot-previous
// （用户实测 920 MB）与 .snapshot-stage（176 MB）在 marker 断言「已提交」之后
// 永远不会再被清理。用户真机实测的正是这一形态（华为 NOH-AN00 / Android 31）。
//
// 为什么必须 try/finally，而不是靠 deletePath 的容错：**marker 的清除不得依赖另一个组件的
// 容错策略**。这条策略已经错过一次——0.14.1 之前 deletePath 只 catch `Exception`，而真机打穿
// 它的恰是 `NoSuchMethodError`（API 34 才有的 Stream.toList；**Error** 而非 Exception），
// 于是一次「清理失败」被放大成 marker 永久残留。
// 0.14.1 D1 已把 deletePath 的容错面扩到 `Exception` + `LinkageError`（见 SnapshotFs），
// 但 try/finally 仍必须留着，理由有两条且都不依赖那次修复的成败：
// ① 非容忍类 `Throwable`（OutOfMemoryError / StackOverflowError 等）**刻意**仍然原样抛出；
// ② 结构上，marker 是恢复权威，它的清除应当是**无条件**的——任何「先在别处判定这次清理
// 算不算成功」的设计都会把同一个死角再造一遍。
// 清理失败可以下一轮重试，marker 残留却会让「下一轮」也永远走同一条路。
try {
delete(previousRoot(filesDir))
delete(stageRoot(filesDir))
} finally {
clearMarker(filesDir)
}
}

fun verdict(declared: String?, actual: Digest): Pair<String, String>? {
if (declared.isNullOrEmpty()) return null
if (declared == actual.hex) return null
return CODE_CORRUPT to (
"内嵌运行时快照资产与安装包内声明值不一致（assets/snapshot.tar.xz 字节被改写/截断）："
+ "expected=" + declared + " actual=" + actual.hex + " bytes=" + actual.bytes
+ "。本次解码未开始即被拦下，现有用户数据未改动；请重新安装完整安装包。"
)
}

internal fun unlockLegacyStorageApi29() {
if (android.os.Build.VERSION.SDK_INT != 29) return
Thread {
try {
// issue #1234：`--user 0` 同样是「写死 user 0」——多用户设备上要操作的是**当前用户**的那个
// 实例（uid / 100000 = Android 用户号，user 10 的 app uid 形如 10xxxxx）。
val currentUser = android.os.Process.myUid() / 100000
val out = ShizukuTransport.runShell(
this,
"appops set --user $currentUser $packageName LEGACY_STORAGE allow" +
" && appops get --user $currentUser $packageName LEGACY_STORAGE",
)
LogCollector.log("dsh-saf", "appop LEGACY_STORAGE: " + out.toString().take(300))
// issue #1234：探测根必须是**当前用户**的共享存储（user 10 → /storage/emulated/10）。
// Environment 拿不到时退回 user 0 拼写（保持旧行为，不放大失败面）。
val sharedStorageRoot = try {
android.os.Environment.getExternalStorageDirectory()?.absolutePath
} catch (_: Throwable) {
null
} ?: WorkspacePickGate.SHARED_STORAGE_ROOT
val probe = ShizukuTransport.runShell(
this,
// issue #1234：探测根必须是**当前用户**的共享存储（user 10 → /storage/emulated/10）。
// 原先写死 /storage/emulated/0，多用户设备上探的是 user 0 的那份 ⇒ 必然失败 ⇒ 上层
// 据此判「存储不可用」。这里用运行期真源拼同一句探测。
"touch " + sharedStorageRoot + "/.dsh-write-probe && rm -f " + sharedStorageRoot
+ "/.dsh-write-probe && echo PROBE_OK",
)
LogCollector.log("dsh-saf", "raw 写探测: " + probe.toString().take(200))
} catch (t: Throwable) {
LogCollector.log("dsh-saf", "appop 解锁失败: " + t.message)
}
}.start()
}

