private fun ensureViewFor(tab: Tab): WebView? {
activeTabId = tab.id
val existing = tab.view
val workspace = requireWorkspace()
if (existing != null) {
if (workspace.profileError.isEmpty() && workspace.profile.isAssigned) return existing
lastError = workspace.profileError.ifEmpty { "browser-profile-not-ready" }
return null
}
val rh = remote
if (rh != null) {
// tier-2：执行位在 :browser 渲染进程；进程边界即隔离，不存在 profile API 面。
if (tab.remoteCreated && workspace.profileError.isEmpty()) return null
if (!rh.ready && !rh.awaitBound(8L)) {
workspace.profileError = "browser-renderer-unavailable"
lastError = workspace.profileError
tab.loadState = "error"
return null
}
rh.refreshEndpoint()
val size = lastStageSize ?: (dshWebView.width.coerceAtLeast(320) to dshWebView.height.coerceAtLeast(480))
val config = JSONObject()
.put("widthPx", size.first).put("heightPx", size.second)
.put("identityId", tab.identityId).put("ua", tab.identityUa)
.put("viewportCssWidth", tab.requestedViewport?.width ?: 0)
val result = runCatching { rh.renderer?.ensureTab(remoteTabId(workspace, tab), root.windowToken, config.toString()) }
.getOrNull()?.let { runCatching { JSONObject(it) }.getOrNull() }
if (result == null || !result.optBoolean("ok")) {
workspace.profileError = result?.optString("reason")?.takeIf { it.isNotEmpty() } ?: "browser-renderer-unavailable"
lastError = workspace.profileError
tab.loadState = "error"
return null
}
rh.setProjectionSize(remoteTabId(workspace, tab), size.first, size.second)
// 新建/重建的投影是一块**全新的** SCVH：去重基线必须作废，否则「几何恰好等于上一次」时
// 会跳过唯一一次必要的 relayout，新投影停在 1x1（#1574 的反向风险）。
pushedGeometry.remove(remoteTabId(workspace, tab))
tab.remoteCreated = true
workspace.profileError = ""
return null
}
val sessionProfile = workspace.profile
if (!BrowserHostProfile.supported()) {
workspace.profileError = "browser-profile-unsupported"
lastError = workspace.profileError
tab.loadState = "error"
return null
}
// provider 会话中更新/被移除时，WebView() 构造本身会抛——走既有错误通道如实报，
// 不让浏览器面板的一次打开把壳侧整个崩掉（与 MainActivity 构造守护同一类故障）。
val created = try {
WebView(activity)
} catch (_: Throwable) {
workspace.profileError = "webview-provider-unavailable"
lastError = workspace.profileError
tab.loadState = "error"
return null
}
// FIRST operation on this WebView: assign and verify its session's nonDefault profile.
// No settings, JS evaluation, bridge, load or root attachment may precede this boundary.
try {
sessionProfile.attach(created)
workspace.profileError = ""
} catch (failure: BrowserHostProfile.Failure) {
workspace.profileError = failure.reason
lastError = failure.reason
tab.loadState = "error"
try { created.destroy() } catch (_: Throwable) { /* Never use the failed view. */ }
return null
}
created.apply {
id = View.generateViewId()
visibility = View.GONE
setBackgroundColor(Color.TRANSPARENT)
// 隔离 WebView 吃「baseline + isolation」两档：版本敏感设置的真源在 WebViewShim。
// （settings.apply{} 是既有线序钉：profile attach 必须先于任何 settings 配置。）
settings.apply {
WebViewShim.applyBaseline(this)
WebViewShim.applyIsolation(this)
}
// 滚动观察（页面真实滚动位置，不注入任何脚本）：驱动可信面板的控件避让与横屏锁定。
// 回调一律写**本 tab** 的状态（闭包捕获 tab），绝不写「当前活动页」——否则后台页的
// 加载/滚动事件会把前台页的状态覆盖掉（多页签下的典型错乱）。
setOnScrollChangeListener { _, _, y, _, oldY ->
tab.scrollY = y
val delta = y - oldY
if (delta > 0) tab.scrollDirection = 1 else if (delta < 0) tab.scrollDirection = -1
}
webViewClient = object : WebViewClient() {
override fun shouldOverrideUrlLoading(view: WebView, request: WebResourceRequest): Boolean {
