val output = ConsoleOutputBatcher(OUTPUT_FLUSH_BYTES, TimeUnit.NANOSECONDS.toMillis(OUTPUT_FLUSH_NS)) { chunk ->
if (generation == gen) listener.onOutput(chunk)
}
try {
(prefetchedReader ?: proc.inputStream.bufferedReader(Charsets.UTF_8)).use { r ->
var next = firstFrame
while (true) {
val line = next ?: r.readLine() ?: break
next = null
val data = ConsolePty.dataOf(line)
if (data != null) {
// 页面用 xterm.js 渲染 VT/ANSI；真 PTY 路径必须原样转发，
// 否则全屏程序（vim/top）的控制序列会被剥掉。仅非 PTY 降级路径继续剥离。
if (data.isNotEmpty()) output.append(data)
continue
}
val op = ConsolePty.fieldOf(line, "op")
if (op == "ready") {
output.flush()
val ready = completePtyHandshake(proc, gen)
if (generation == gen) {
if (ready) listener.onStatus(State.READY, "bash 已就绪（快照 Termux 环境，真 PTY）")
else listener.onStatus(State.FAILED, UiText.t(context,
"PTY 输入重放失败——请重连后重试", "PTY input replay failed. Reconnect to retry."))
}
} else if (op == "error") {
// I4：中继启动期 error 后会立即 process.exit——它不会再服务任何输入，
// 旧实现仍报 READY 是把死会话说成可用。如实报 FAILED（重连有意义），
// 进程退出由下方 EOF 兜底（exit 帧不会再来）。
val msg = ConsolePty.fieldOf(line, "message") ?: "未知错误"
Log.w(TAG, "console relay error: " + msg)
output.flush()
if (generation == gen) listener.onStatus(State.FAILED, "PTY 建立失败：" + msg + "——可点重连重试")
} else if (op == "exit") {
val code = ConsolePty.numberFieldOf(line, "code") ?: -1
exitSeenByReader = true
output.flush()
if (generation == gen) listener.onExit(code)
}
}
}
} finally {
output.close()
}
} else {
// 非 PTY 降级路径：与旧实现一致，按块读并剥离控制序列。
proc.inputStream.reader(Charsets.UTF_8).use { r ->
val raw = CharArray(1024)
val sb = StringBuilder()
while (true) {
val n = r.read(raw)
if (n < 0) break
sb.append(stripper.feed(String(raw, 0, n)))
if (sb.length >= 4096 || sb.indexOf("\n") >= 0) {
val chunk = sb.toString()
sb.setLength(0)
if (generation == gen) listener.onOutput(chunk)
}
}
if (sb.isNotEmpty() && generation == gen) listener.onOutput(sb.toString())
}
}
} catch (t: Throwable) {
if (!closed) Log.w(TAG, "console reader ended: " + (t.message ?: t.javaClass.simpleName))
}
val code = try {
proc.exitValue()
} catch (_: IllegalThreadStateException) {
-1
}
// EOF 兜底（I4 同族）：PTY 模式下 exit 帧已报过就不再重复；error 后中继自退没有
// exit 帧，EOF 是唯一退出信号——旧实现只给非 PTY 路径报 onExit，死会话永远「就绪」。
if (generation == gen) {
synchronized(inputLock) { if (generation == gen) ptyReady = false }
if (!canUsePty || !exitSeenByReader) listener.onExit(code)
}
}
/**
* 页面尺寸变化时调用。
*
* @param cols 列数（页面按字符度量估算）。
* @param rows 行数。
*/
fun resize(cols: Int, rows: Int) {
val (c, r) = ConsolePty.normalizeSize(cols, rows)
if (c == this.cols && r == this.rows) return
this.cols = c
this.rows = r
// I2：resize 帧只对 PTY 中继有意义；非 PTY 降级下 process 就是 bash 本身，
// 往它 stdin 写 JSON 帧等于注入一条命令（页面加载即触发一次）。降级的初始
// 尺寸已由 DSH_CONSOLE_COLS/ROWS 环境变量交付。
if (usingPty) send(ConsolePty.resizeMessage(c, r))
}
/** Write one command (appends \n). */
fun writeCommand(cmd: String) {
writeRaw(cmd + "\n")
}
/**
* 写入原始字节（不追加换行）。
*
* 有了真 PTY 之后，方向键、Ctrl-C、Tab 补全都是裸控制字符；
* 只提供"整行命令"的入口等于把这些能力挡在门外。
*
* @param text 要写入的文本（可含控制字符）。
*/
fun writeRaw(text: String) {
synchronized(inputLock) {
val proc = process ?: return
if (usingPty && !ptyReady) {
// Readiness and queue insertion share the ready handler's critical section.
pendingInput.append(text)
return
}
if (ptyReady) {
send(ConsolePty.writeMessage(text))
return
}
try {
proc.outputStream.write(text.toByteArray(Charsets.UTF_8))
proc.outputStream.flush()
} catch (t: Throwable) {
Log.w(TAG, "console write failed: " + (t.message ?: t.javaClass.simpleName))
}
}
}
/** Serializes readiness, queued replay and later input for the current relay. */
internal fun completePtyHandshake(proc: Process, gen: Int): Boolean = synchronized(inputLock) {
if (closed || generation != gen || process !== proc) return@synchronized false
val replay = pendingInput.toString()
pendingInput.setLength(0)
if (replay.isNotEmpty()) {
try {
proc.outputStream.write(ConsolePty.writeMessage(replay).toByteArray(Charsets.UTF_8))
proc.outputStream.flush()
} catch (t: Throwable) {
Log.w(TAG, "console pending replay failed: " + (t.message ?: t.javaClass.simpleName))
return@synchronized false
}
}
ptyReady = true
true
}
/** Serializes protocol frames with handshake replay and ordinary input. */
private fun send(line: String) {
synchronized(inputLock) {
val proc = process ?: return
try {
proc.outputStream.write(line.toByteArray(Charsets.UTF_8))
proc.outputStream.flush()
} catch (t: Throwable) {
Log.w(TAG, "console relay write failed: " + (t.message ?: t.javaClass.simpleName))
}
}
}
/** 当前是否运行在真 PTY 下（页面据此决定是否显示按键条）。 */
fun hasPty(): Boolean = ptyReady
fun isAlive(): Boolean {
val proc = process ?: return false
return try {
proc.exitValue()
false
} catch (_: IllegalThreadStateException) {
true
}
}
fun restart(listener: Listener): Boolean {
generation += 1
destroy()
closed = false
stripper.reset()
synchronized(inputLock) { pendingInput.setLength(0) }
return start(listener)
}
/**
* Terminate the session (Activity destroyed).
*
* 先给中继发 kill 让它按协议回收 PTY 子进程，再 destroy 兜底：
* 只 destroy 中继会留下「pty 已关、bash 还在跑」的孤儿（vim/top 实测残留）。
*/
fun destroy() {
closed = true
// M-c4：与后台 start 竞速时作废在途会话的回调（读线程的 generation 判据随之失效）。
generation += 1
val proc = process
process = null
if (proc != null) {
if (ptyReady) {
// C1：kill 帧必须直写局部 proc——旧实现此刻已把字段置 null，而 send 读的是字段，
// kill 协议沦为死代码：实际回收只剩 SIGKILL 中继，vim/top 的 PTY 子进程全部残留。
try {
proc.outputStream.write(ConsolePty.KILL_MESSAGE.toByteArray(Charsets.UTF_8))
proc.outputStream.flush()
} catch (_: Throwable) {
}
// 给中继短窗按协议回收 PTY 子进程；不给窗的话紧随的 destroy 会与 kill 帧竞争。
try {
proc.waitFor(500, TimeUnit.MILLISECONDS)
} catch (_: InterruptedException) {
Thread.currentThread().interrupt()
}
}
ptyReady = false
proc.destroy()
}
}
companion object {
private const val TAG = "dsh-console"
private const val NATIVE_RELAY = "libdsh_console_relay.so"
/** 输出聚合阈值（I7）：16KB 或 50ms 先到者触发一次回调。 */
internal const val OUTPUT_FLUSH_BYTES = 16 * 1024
internal const val OUTPUT_FLUSH_NS = 50_000_000L
/** 中继脚本解包完成标记（M-c4：进程级一次，重连/重开不再重打资产 IO）。 */
@Volatile private var relayUnpacked = false
}
}

private fun noteWakeActivityForTick(epoch: ServiceEpoch) {
val liveLength = WatchdogV2.liveFeedLength(this)
val previous = epoch.lastLiveFeedLength
epoch.lastLiveFeedLength = liveLength
if (previous >= 0L && liveLength > previous) {
noteWakeActivity()
}
val nowMs = System.currentTimeMillis()
val bootAgeMs = nowMs - EngineManager.lastStartAttemptAt
if (engineManager.engineProcessAlive() && bootAgeMs in 0 until EngineManager.START_COOLDOWN_MS) {
noteWakeActivity()
}
}

private fun watchdogTick(epoch: ServiceEpoch, exec: ScheduledExecutorService) {
// 下一拍间隔：try 与 catch 两侧都要写，故声明在外（默认取非健康节奏 5 秒）。
var nextDelayMs = WatchdogV2.ACTIVE_TICK_MS
try {
if (!isEpochCurrent(epoch) || epoch.watchdog.get() !== exec) return
val now = System.currentTimeMillis()
// §6.3（0.14.10）：本拍实际经过多久 → 折算成多少个「标准拍（5 秒）」记账。
// 阶梯阈值（30s/60s/90s）都按 5 秒拍标定：健康态退到 20 秒一拍后，若仍按「一拍 = 一个
// 阶梯单位」计数，30 秒的阶梯会变成 120 秒。issue #1357：时钟必须单调（与唤醒锁同域）。
// issue #1505：单调时钟**含深睡**，而 doze 期间 postDelayed 不执行 ⇒ 唤醒后必然出现一个
// 巨大 tickMs。它不能算「连续失败」的观测：tickAccounting 把缺口拍按**一个**标准拍记账
// 并给 gap（旧实现封顶 6 拍 ⇒ 两拍就把 DEGRADED_HTTP 推满 12 拍熔断）。
// 首拍（lastWatchdogTickAt = 0）仍按一个标准拍处理：不能把它当成「隔了很久」。
val mono = android.os.SystemClock.elapsedRealtime()
val tickMs = if (epoch.lastWatchdogTickAt <= 0L) 0L else mono - epoch.lastWatchdogTickAt
epoch.lastWatchdogTickAt = mono
val accounting = WatchdogV2.tickAccounting(tickMs)
val units = accounting.units
if (accounting.gap) LogCollector.log("dsh-watchdog", accounting.log)
// 本拍探活状态（用于定下一拍节奏；异常拍保持非健康节奏）。
var tickState: WatchdogV2.ProbeState? = null
// 启动流正在排队重试或修复助手持有闸门时，后台不得同时重启、回撤或改写
// 正在被修复的运行时。保留通知消费与唤醒锁续期：它们不解耦地改写运行时状态。
if (RepairState.required(this) || RepairState.active || RepairState.retryPending) {
NotifyStore.drainTick(this)
if (!isEpochCurrent(epoch)) return
noteWakeActivityForTick(epoch)
WatchdogV2.refreshWakeLock(this, epoch.wakeOwner)
// 修复态不打探活 ⇒ 保持非健康节奏（5 秒）复看，不拖到 20 秒。
nextDelayMs = WatchdogV2.ACTIVE_TICK_MS
// 本拍到此为止（后台不得重启、回撤或改写正在被修复的运行时），但**下一拍必须挂回去**：
// 重排在 finally 里，这里 return 也会走到。旧实现是直接 return 跳过尾部重排，而
// scheduleWatchdogTick 全仓只有首拍与尾部两个调用点 ⇒ 修复态一出现 tick 链就永久断死
// （issue #1354：探活、自动重启、通知 drain 一起停摆，直到 Service 重建）。
return
}
// P1（0.14.1 通知停摆修复）：通知信道消费的**兜底驱动**（`NotifyStore` 的 drainTick）。
// 它必须在本拍的任何状态判定之前执行——引擎 HEALTHY 时也要消费，而在 DEAD/DEGRADED 各态下
// 更是唯一活着的消费者（真机停摆现场：`.notify.ndjson` 一直在长，而事件驱动的消费一条也没
// 投出去，只有这条 5 s 心跳的日志还在更新）。幂等 + 一次 stat，不改本拍语义，失败也不冒泡。
NotifyStore.drainTick(this)
if (!isEpochCurrent(epoch)) return
// §6.2：本拍开始前先刷新活动信号（turn 在跑 / 启动或重启窗口）。它必须在
// planTick 之前——refreshWake 是 planTick 的前置副作用，读到的是本拍的租约状态。
noteWakeActivityForTick(epoch)
if (!isEpochCurrent(epoch)) return
val state = WatchdogV2.assessProbe(this) { isEpochCurrent(epoch) }
tickState = state
if (!isEpochCurrent(epoch)) return
// UndoGate 的历史健康记录在 0.14.8 起不再更新：插件已退役，壳侧不再运行自动 undo。
// 急救 CLI 与已有快照仍保留给用户手动恢复。
if (!isEpochCurrent(epoch)) return
// FX-210.2/.3/.4：决策与状态无关副作用全部落在 planTick 的前置段（先于一切早退，
// 含熔断打开的那一拍），调用方只执行返回的破坏性动作。退避/熔断同用
// effectiveFailureCount（半死阶梯与 DEAD 共用计数，见 #175/#210.2）。
val plan = WatchdogV2.planTick(
state = state,
now = now,
nextRestartAllowedAt = epoch.nextRestartAllowedAt,
engineReady = engineManager.engineReady,
engineProcessAlive = engineManager.engineProcessAlive(),
bootAgeMs = now - EngineManager.lastStartAttemptAt,
restartDeadConfirmations = restartDeadConfirmations,
// 【issue #274 ①】端口归属的**生产口径**。
//
// 口径是「本进程是否托管着一个活着的引擎子进程」，而不是去反查 3080 的监听者：
// · 探活处于 DEGRADED_HTTP 时端口**必然可连**（否则会是 DEAD）；
// · 此刻若我们确有活着的托管子进程 ⇒ 端口几乎必然是我们的（半死档）；
// · 若我们没有任何托管子进程而端口仍可连 ⇒ 占着它的是**别人**，
// 此时盲目重启只会撞 EADDRINUSE，先 HOLD 并留诊断行。
//
// 这是**代理判据**，不是内核级归属证明（本仓无 netstat/uid 反查的设备无关通道）。
// 它偏保守：只有在「我们没有活子进程」时才判为他人占用。
// 自愈性：他人进程退出后端口不再可达 ⇒ 状态转为 DEAD ⇒ 该门不再适用（degradedLadderTripped=false），
// 重启路径照常恢复，不会形成永久死局。
// #1576：必须用「托管子进程是否活着」，不能用 engineProcessAlive()（它在无句柄时退回端口可达性，恒真）。
portOwnedByApp = engineManager.trackedChildAlive(),
feedProbe = { healthy -> if (isEpochCurrent(epoch)) engineManager.onEngineProbe(healthy) },
consumeMarkers = { if (isEpochCurrent(epoch)) WatchdogV2.consumeTaskDoneMarkers(this) },
refreshWake = { if (isEpochCurrent(epoch)) WatchdogV2.refreshWakeLock(this, epoch.wakeOwner) },
// 自动 undo 主代理已断开运行调用（0.14.8）：看门狗只做探活与受控重启。
// UndoGate 类保留为历史实现，手动急救入口不受影响。
undoReady = { false },
callerCurrent = { isEpochCurrent(epoch) },
// §6.3：按本拍真实间隔折算的标准拍数记账（20 秒拍 = 4 个标准拍）。
units = units,
)
if (!isEpochCurrent(epoch)) return
// §6.3：只有健康且不在冷启动窗口时才用 20 秒拍；DEGRADED_*/DEAD/冷启动一律回到
// 5 秒（tickState 是本拍真实探活结论，不看上一拍，恢复不会被长间隔拖成三倍）。
nextDelayMs = WatchdogV2.nextTickDelayMs(tickState ?: WatchdogV2.ProbeState.DEAD, booting = isBootingWindow())
for (line in plan.logs) {
if (!isEpochCurrent(epoch)) return
LogCollector.log("dsh-watchdog", line)
}
if (!isEpochCurrent(epoch)) return
when (plan.action) {
WatchdogV2.TickAction.IDLE -> {
epoch.nextRestartAllowedAt = 0L
}
WatchdogV2.TickAction.HOLD -> Unit
WatchdogV2.TickAction.UNDO -> Unit
WatchdogV2.TickAction.RESTART -> {
if (!isEpochCurrent(epoch)) return
if (plan.force) {
engineManager.mirrorDiagnosticsToShared("engine-boot-hung")
LogCollector.log("dsh-watchdog", "tracked child exceeded boot deadline; forcing one controlled restart")
} else if (now - epoch.lastDeathMirrorAt >= DEATH_MIRROR_INTERVAL_MS) {
// review C5：确认死亡的常态重启也镜像现场（10 分钟节流）——后台崩溃循环下
// 旧实现只在 force 档镜像，轮转几拍后原始 engine.log 已被滚掉，取证现场丢失。
val dir = engineManager.mirrorDiagnosticsToShared("engine-died")
if (dir != null) epoch.lastDeathMirrorAt = now
LogCollector.log("dsh-watchdog", "engine death diagnostics: " + (dir?.absolutePath ?: "unavailable"))
}
if (!isEpochCurrent(epoch)) return
// §6.2：重启窗口算活动——noteWakeActivity 内部即按新租约重取唤醒锁
// （有事件立即重取，不等下一拍），冷启动期间的 CPU 不会被放掉。
noteWakeActivity()
// issue #684：让行（刷新中）不算「已发起」——日志要如实区分，否则排障时
// 「accepted=true 但进程不在」无法归因。
val startOutcome = engineManager.startEngine(force = plan.force)
val requested = startOutcome == EngineStartOutcome.STARTED
if (!isEpochCurrent(epoch)) return
val delayMs = WatchdogV2.nextDelayMs()
epoch.nextRestartAllowedAt = now + delayMs
LogCollector.log(
"dsh-watchdog",
"restart requested after confirmed failure #" + WatchdogV2.effectiveFailureCount() +
" (accepted=" + requested + ", outcome=" + startOutcome + ", next eligible in " + delayMs + "ms)",
)
}
}
} catch (t: Throwable) {
if (!isEpochCurrent(epoch)) return
Log.e("dsh-watchdog", "watchdog tick failed", t)
LogCollector.log("dsh-watchdog", "watchdog tick failed: " + (t.message ?: t.javaClass.simpleName))
if (isEpochCurrent(epoch)) WatchdogV2.refreshWakeLock(this, epoch.wakeOwner)
// 异常拍按「非健康」收口：下一拍回到 5 秒节奏复看。
nextDelayMs = WatchdogV2.ACTIVE_TICK_MS
} finally {
// §6.3：单次延迟重排——旧 scheduleWithFixedDelay 的固定 5 秒节奏换成按状态自适应。
// 判定全部收口在 nextDelayMs，本处只负责「什么时候再看一眼」。
// 为什么在 finally 而不是 try 之后：本拍**任何**早退（修复态、换代、异常）都必须把下一拍
// 挂回去，否则 tick 链断死（issue #1354）。停机与换代由这两个判据兜住，不会多出一条链。
if (isEpochCurrent(epoch) && epoch.watchdog.get() === exec) {
scheduleWatchdogTick(epoch, exec, nextDelayMs)
}
}
}

override fun onCreate(savedInstanceState: Bundle?) {
super.onCreate(savedInstanceState)
OverlayHostVisibility.install(application)
// 性能审计 #6：冷启动细分段基准。开发者调试开关关闭时本行只读一次已缓存的布尔值，
// 不取时刻、不碰磁盘（见 BootPhaseTrace 头注「有界性」）。
//
// issue #1338：这一行与下面两处 mark() 曾被 9fe627a8（perf(overlay) 动效开关）在
// 同一批提交里静默删掉——markBootBase 只剩声明、全仓无调用者，onCreate 与
// webViewConstruct 两个阶段不再产生记录，剩下两个阶段的 at= 全部重新基准。
// BootPhaseTraceTest 当时仍绿（它只断言常量存在，不断言调用点），所以补了
// BootPhaseCallSiteTest 把「每个阶段常量必须有调用点」变成可判的。
BootPhaseTrace.markBootBase(this)
// 本实例的原生视图树是按创建时的界面语言构建的；桥在运行期改语言后靠
// refreshUiLanguageIfChanged() 在启动页再次出现前重建。
photoCaptureController.restoreNow(); appliedUiLanguage = AppLanguage.mode(this) // P0：恢复必须在这里（super.onCreate 之后），不能放控制器 init——那时未 attachBaseContext，cacheDir 为 null ⇒ getCacheDir() NPE。相机结果只经 onNewIntent/onActivityResult 投递，都在 onCreate 之后，时序不变。
// 0.14.9：「打开应用后自动启动」是用户的显式意图，冷启动时优先于上一次的持久化停机标记。
// 旧行为把「划过任务卡/手动停止」留下的 userShutdown 一路带到下次打开，开关明明开着却
// 停在启动页——看起来就是开关失效。同一次会话内的停止仍由 savedInstanceState 保留，
// 只有真正的冷启动（savedInstanceState == null）才按开关清除持久标记。
// issue #945：覆盖安装后先把**上一版的**起动意图归一，再读开关。
// 顺序不能反：若先读 `autoStart`，残留的 false 会直接决定下面的分支，归一等于没做。
StartupPrefsNormalizer.resetOnUpgrade(this)
val autoStartOnOpen = SplashStore.autoStart(this)
userClosedEngine = if (savedInstanceState == null && autoStartOnOpen) {
EngineService.setUserShutdown(this, false)
false
} else {
(savedInstanceState?.getBoolean("dsh.engine-user-closed", false) ?: false) ||
EngineService.userShutdown || EngineService.isUserShutdownPersisted(this)
}
if (userClosedEngine) EngineService.userShutdown = true
pageRecovery.restoreRecreationBudget(savedInstanceState?.getBoolean("dsh.renderer-recreation-attempted", false) ?: false)
// 0.13.3 W2：引擎鉴权模块绑定应用上下文（EngineProbe 等 object 调用方的 cookie 来源）。
EngineAuth.initContext(this)
// 崩溃标记：进程级未捕获异常写入 filesDir/.crashed（下次启动测试界面
// 提示），随后交回默认 handler——只记录，不吞异常、不阻止崩溃。
installCrashMarker()
// 启动即 TTL 清扫临时工作区（issue #60 F5.1：7 天过期文件自动回收）
//
// 性能审计 2026-11-02 #5：**移出主线程**。
//
// 原实现直接在 onCreate 同步跑：sweepWorkspace 会 listFiles() 整个来件临时工作区，
// 再对 `.sessions` 下**每个 json 各做一次 readText + JSONObject 解析**，最后逐条 stat。
// 这是本 Activity 唯一一处「随用户来件量增长」的主线程冷启成本，且上界无硬限
// （TTL 是 7 天，重度用户可以让 .sessions 累积数百条）。
//
// 为什么挪走是**零行为变化**：它的语义只是「删掉 7 天前的过期临时文件」，早两秒晚两秒
// 对用户没有任何可观测差异。与 processIncomingIntent 的顺序也不构成正确性问题——
// 新来件 age=0，永远不在 TTL 删除集里（sweepWorkspace 只删 lastModified < now - TTL 的项）。
// 异常仍按原样吞掉（清扫失败不得影响启动）。
Thread({
try { FileIncoming.sweepExpired(this) } catch (_: Throwable) {}
