override fun capture(): JSONObject {
val manager = context.getSystemService(DisplayManager::class.java)
val screens = JSONObject()
val displaySupport = JSONObject()
val displayOperations = JSONObject()
val operations = linkedSetOf<String>()
fun publishDisplay(alias: String, display: Display, allocationId: Long? = null) {
if (!display.isValid) return
val displayId = display.displayId
val size = Point()
display.getRealSize(size)
val rotation = when (display.rotation) {
Surface.ROTATION_0 -> 0
Surface.ROTATION_90 -> 1
Surface.ROTATION_180 -> 2
Surface.ROTATION_270 -> 3
else -> return
}
val screen = JSONObject().put("displayId", displayId).put("width", size.x)
.put("height", size.y).put("rotation", rotation)
if (allocationId != null) screen.put("allocationId", allocationId.toString())
screens.put(alias, screen)
val available = execution.supportedOperations(displayId)
operations.addAll(available)
displaySupport.put(displayId.toString(), available.isNotEmpty())
displayOperations.put(displayId.toString(), JSONArray(available))
}
manager.getDisplay(Display.DEFAULT_DISPLAY)?.let { publishDisplay("real", it) }
// Keep each alias, Android Display object, and identity from the same owner snapshot.
val allocations = VdisplayController.nativeDisplayAllocations()
val registeredDisplayIds = allocations.mapNotNull { allocation ->
runCatching { allocation.display.displayId }.getOrNull()
}.toSet()
for ((alias, display, allocationId) in allocations) {
publishDisplay(alias, display, allocationId)
}
val enabled = try {
val expected = ComponentName(context, DeviceControlService::class.java)
val services = Settings.Secure.getString(context.contentResolver, Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES)
if (services.orEmpty().split(':').any { ComponentName.unflattenFromString(it) == expected }) "yes" else "no"
} catch (_: Exception) { "unknown" }
val online = if (DeviceControlService.nativePlatformService() != null) "yes" else "no"
val shizukuFacts = shizuku.snapshot()
// per-display 事实只对「本应用此刻仍注册」的屏成立：真实屏恰好是 display 0，
// 其余必须还在 VdisplayController 的分配表里。已销毁的屏立刻从事实面消失，
// 不让上一轮的实测位残留到下一次派发。
val measured = shizukuFacts.optJSONObject("displayOperations")
if (measured != null) {
val live = JSONObject()
for (key in measured.keys()) {
val id = key.toIntOrNull() ?: continue
if (id == Display.DEFAULT_DISPLAY || id in registeredDisplayIds) live.put(key, measured.get(key))
}
if (live.length() > 0) {
shizukuFacts.put("displayOperations", live)
val values = JSONObject()
for (key in live.keys()) values.put(key, true)
shizukuFacts.put("displaySupport", JSONObject().put("state", "known").put("values", values))
// supportedOps 必须只反映仍然存活的屏：已销毁屏的 op 不得留在并集里，
// 否则缺 displayOperations 的回退路径会拿它冒充支持。
val union = org.json.JSONArray()
for (key in live.keys()) {
val operations = live.optJSONArray(key) ?: continue
for (index in 0 until operations.length()) {
val operation = operations.optString(index)
if (operation.isEmpty()) continue
if ((0 until union.length()).any { union.optString(it) == operation }) continue
union.put(operation)
}
}
shizukuFacts.put("supportedOps", if (union.length() > 0)
JSONObject().put("state", "known").put("ops", union)
else JSONObject().put("state", "unknown"))
} else {
// 一块屏都没测到：整键缺席并把支持表降为未知，让 Rust 走「未知不冒充否」的判定。
shizukuFacts.remove("displayOperations")
shizukuFacts.put("displaySupport", JSONObject().put("state", "unknown"))
// 并集也一并收回：不能留下只属于已销毁屏的 op。
shizukuFacts.put("supportedOps", JSONObject().put("state", "unknown"))
}
}
if (shizukuFacts.optString("functionalReady") == "yes" && shizukuFacts.optString("granted") == "yes" &&
shizukuFacts.optJSONObject("serverUid")?.optString("kind") == "shell2000") {
val supported = shizukuFacts.optJSONObject("supportedOps")?.optJSONArray("ops") ?: JSONArray()
for (operation in listOf("vdCreate", "vdDestroy", "vdInfo", "vdLaunch", "vdLaunchApp")) supported.put(operation)
shizukuFacts.put("supportedOps", JSONObject().put("state", "known").put("ops", supported))
}
return JSONObject().put("scope", scope()).put("observedAtMs", System.currentTimeMillis())
.put("screens", screens)
.put("a11y", JSONObject().put("enabled", enabled).put("online", online)
.put("supportedOps", JSONObject().put("state", "known").put("ops", JSONArray(operations.toList())))
.put("displaySupport", JSONObject().put("state", "known").put("values", displaySupport))
.put("displayOperations", displayOperations))
.put("shizuku", shizukuFacts)
.put("root", runCatching {
JSONObject().put("authorization", if (RootGrant.isGranted(context)) "yes" else "no")
.put("consentValid", if (RootGrant.consentValid(context)) "yes" else "no")
}.getOrElse { JSONObject().put("authorization", "unknown").put("consentValid", "unknown") })
}

fun create(context: Context, args: JSONObject? = null, authorize: (() -> Boolean)? = null): JSONObject {
val appContext = context.applicationContext
val session = args?.optString("session", "")?.takeIf { it.isNotBlank() }
// 0.14.0 用户口径修正：**隔离「可见性/操作」，但共享「物理资源」**。
//
// 为什么不是「每会话一块屏」：虚拟屏是**全局稀缺资源**（本版上限 MAX_VIRTUAL_DISPLAYS = 1，
// 一块 VirtualDisplay 在系统里真实占位）。若按会话各持一块，第 2 个会话必然撞上限。
// 我自己上一版就犯了这个错：幂等判断写成「本会话是否已有屏」，于是
// 面板先建屏(owner=null) → 模型再建(owner=X) 被算作「本会话没有屏」→ 尝试建第 2 块 → 报上限。
//
// 正确的隔离边界：
// - 资源：**全局唯一**（上限就是上限，谁建都算同一块）；
// - 归属：只用于「呈现给谁看」（面板按会话显示），**不再用于拒绝操作**；
// - 销毁：任何会话都能关（用户明确要求，否则创建者消失后没人能关）。
//
// 因此幂等判断回到「本机是否已有屏」——存在即复用，无论它当初由谁创建。
val existing = synchronized(lock) { records.size }
if (existing > 0) return if (authorize == null || authorize()) status(appContext) else nativeDenied()
val bound = ShizukuTransport.ensureBound(appContext)
if (!bound.optBoolean("ok")) return status(appContext)
.put("code", bound.optString("code", "shizuku-not-ready"))
.put("guidance", bound.optString("guidance", "Shizuku 未就绪。"))
// #520：旧版此处曾有 `existing >= MAX_VIRTUAL_DISPLAYS → vdisplay-limit` 分支，但它被上面的
// 幂等复用早退（existing > 0 即 return）挡成死代码——MAX=1 时上限语义由「存在即复用」表达，
// vdisplay-limit 错误码永不返回。刻意删除而非保留：未来把 MAX 调大时，放行面在这里补回
// 上限分支并同步幂等早退条件（复用仅应发生在「未达上限」时），而不是让两个入口互相矛盾。
val real = DisplayMetrics()
@Suppress("DEPRECATION")
(appContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager).defaultDisplay.getRealMetrics(real)
val scale = (args?.optDouble("scale", VdisplayPrefs.scale(appContext)) ?: VdisplayPrefs.scale(appContext))
.coerceIn(0.4, 1.0)
val width = (args?.optInt("width", 0) ?: 0).takeIf { it > 0 }?.coerceIn(MIN_EDGE, MAX_EDGE)
?: Math.round(real.widthPixels * scale).toInt().coerceIn(MIN_EDGE, MAX_EDGE)
val height = (args?.optInt("height", 0) ?: 0).takeIf { it > 0 }?.coerceIn(MIN_EDGE, MAX_EDGE)
?: Math.round(real.heightPixels * scale).toInt().coerceIn(MIN_EDGE, MAX_EDGE)
synchronized(lock) {
var nextReader: ImageReader? = null
var nextThread: HandlerThread? = null
try {
val dpi = (args?.optInt("densityDpi", 0) ?: 0).takeIf { it > 0 }?.coerceIn(120, 640)
?: Math.round(real.densityDpi * scale).toInt().coerceIn(120, 640)
nextThread = HandlerThread("dsh-vdisplay-reader").also { it.start() }
nextReader = ImageReader.newInstance(width, height, PixelFormat.RGBA_8888, 2)
nextReader.setOnImageAvailableListener({ source ->
// This is not a pixel transport. Drain and close frames so the owned output surface stays
// healthy while the visual viewer surface is attached separately.
runCatching { source.acquireLatestImage()?.close() }
}, Handler(nextThread.looper))
// flags 组合（0.14.0 模拟器两轮实锤，两个方向都踩过，**不要再改**）：
//
// ✅ `PUBLIC | OWN_CONTENT_ONLY | SUPPORTS_TOUCH | DESTROY_CONTENT_ON_REMOVAL | ROTATES_WITH_CONTENT`
// ❌ 去掉 OWN_CONTENT_ONLY → 创建直接抛：
// SecurityException: Requires ADD_MIRROR_DISPLAY, CAPTURE_VIDEO_OUTPUT or
// CAPTURE_SECURE_VIDEO_OUTPUT permission, or an appropriate MediaProjection token
// ... please use the flag VIRTUAL_DISPLAY_FLAG_OWN_CONTENT_ONLY.
// 即：不带该 flag，系统按「屏幕共享/镜像」处理，而镜像需要投屏权限（我们没有）。
// 该 flag 是**非系统应用创建虚拟屏的必备条件**，故必须保留。
//
// 实测 dumpsys 的最终形态：`FLAG_ROTATES_WITH_CONTENT, FLAG_OWN_CONTENT_ONLY,
// FLAG_DESTROY_CONTENT_ON_REMOVAL`（**没有 FLAG_PUBLIC**——Android 13+ 起 PUBLIC 只对系统应用生效，
// 应用自建的虚拟屏一律为 private，只能显示 owner 自己的窗口）。
//
// 这条结论的直接后果见 launchApp()。**2026-09-19 判定性实测更正**：原文写「private 屏上
// **无法把第三方应用拉进来**（SafeActivityOptions.checkPermissions 拒；已验证 uid 2000 与
// uid 10053 两条路都被拒）」——该结论在 MuMu x86_64 / API 35 上**不成立**：第三方应用
// `com.endday.game` 经 `am start --display 2` 成功落在 display 2（普通 adb shell uid 2000
// 与壳侧 UserService 两条路都试过）。故按实测改写为：**本机型成立、其它 ROM 待复核**；
// 判定落点不靠这条前提，而由 launchApp 的落点回读（displaysRunning）如实回报。
val flags = FLAG_PUBLIC or FLAG_OWN_CONTENT_ONLY or FLAG_SUPPORTS_TOUCH or
FLAG_DESTROY_CONTENT_ON_REMOVAL or FLAG_ROTATES_WITH_CONTENT
val manager = appContext.getSystemService(Context.DISPLAY_SERVICE) as DisplayManager
// 序号分配（0.14.0 用户实报修正）：**复用已释放的序号**，而不是单调递增。
//
// 旧实现每建一块就 `nextAliasIndex += 1` 且从不回收，于是反复建/销毁会得到
// virtual-1 → virtual-2 → virtual-3 …（实测复现）。三步后果：
// 1) 序号无限膨胀，模型看到的别名与「本机有几块屏」脱节；
// 2) 上限只有 1 块时，界面显示「虚拟屏 3」却切不回之前那块，用户无法理解；
// 3) 与用户对「编号 = 当前屏幕的标识」的直觉冲突。
//
// 现在从 1 起找**最小的未占用序号**（被销毁的号立刻可复用），因此稳定表现为：
// 没有屏时新建恒为 virtual-1；有 1 块时第二块才是 virtual-2（但上限 1，见 MAX_）。
val alias = run {
var candidate = 1
while (records.containsKey("virtual-$candidate")) candidate += 1
"virtual-$candidate"
}
if (authorize != null && !authorize()) {
nextReader.close(); nextThread.quitSafely()
return nativeDenied()
}
val created = manager.createVirtualDisplay(
"DSH $alias",
width,
height,
dpi,
nextReader.surface,
flags,
) ?: throw IllegalStateException("DisplayManager returned null VirtualDisplay")
records[alias] = Record(alias, created, ++lastAllocationId, nextReader, nextThread, width, height, dpi,
owner = session)
if (selectedAlias == null) selectedAlias = alias
if (ownerSessionId == null && session != null) ownerSessionId = session
generation += 1
lastCode = "vdisplay-active"
lastGuidance = "$alias 已创建。"
Log.i(TAG, "created alias=$alias displayId=${created.display.displayId} size=${width}x$height dpi=$dpi generation=$generation")
return status(appContext)
} catch (t: Throwable) {
runCatching { nextReader?.close() }
runCatching { nextThread?.quitSafely() }
lastCode = if (t is SecurityException) "vd-denied-flags" else "vd-create-failed"
lastGuidance = t.javaClass.simpleName + ": " + (t.message ?: "")
Log.w(TAG, "create failed $lastGuidance")
return status(appContext).put("code", lastCode).put("guidance", lastGuidance)
}
}
}

private fun applyStageBounds() {
val bounds = stageBounds
val cssWidth = bounds?.viewportWidth ?: 0.0
val cssHeight = bounds?.viewportHeight ?: 0.0
if (bounds == null || !bounds.visible || cssWidth <= 0.0 || cssHeight <= 0.0 ||
bounds.width <= 1.0 || bounds.height <= 1.0 || root.width <= 0 || root.height <= 0 ||
dshWebView.width <= 0 || dshWebView.height <= 0
) {
stageVisible = false
resetFullscreen()
view?.visibility = View.GONE
return
}
// ── 冻结态限频守卫（双守卫之二）──────────────────────────────────────────
// 被仲裁拒绝后 30s 内保持 GONE、纯计算早退：不重试、不翻转可见性、不触碰控制器
// （现状每帧 attachViewerSurface 拿锁并构造全量 status JSON 的供能腿在此断根）。
// stageVisible 如实回报 false，reason 保留 bindSurface 写入的拒绝码。
if (bindRefused) {
val sinceRefused = android.os.SystemClock.elapsedRealtime() - lastRefusedAtMs
if (sinceRefused < REBIND_BACKOFF_MS) {
stageVisible = false
if (view?.visibility != View.GONE) view?.visibility = View.GONE
fullscreenButton?.let { if (it.visibility != View.GONE) it.visibility = View.GONE }
return
}
// 过窗：放行到下方唯一 retry 路径（被拒则 bindSurface 刷新时间戳，成功则清冻结）。
}
val surface = ensureView()
// 等比适配统一 scale（0.14.10 issue ③ 修复）：只取 X 基准（viewWidth/cssWidth），不再用
// dshWebView.height 派生 scaleY——IME 弹起时页面 css 视口高度经 padding 缩短会让 scaleY
// 虚增、舞台盒纵向放大（「半截画面」）。cssWidth 非法时 uniformScale 返回 0。
val scale = VdisplayLetterbox.uniformScale(dshWebView.width, cssWidth)
if (scale <= 0.0) {
stageVisible = false
resetFullscreen()
view?.visibility = View.GONE
return
}
// 舞台矩形：页面 CSS 舞台 coerce 进 root（既有 coerce 行为的等价抽取）；全屏时取 root 全域
// （contain 数学不变，黑边留在全屏域内）。
val stage = if (fullscreen) {
VdisplayLetterbox.Frame(0, 0, root.width, root.height)
} else {
VdisplayLetterbox.stageRectInRoot(
(bounds.left * scale).toInt(),
(bounds.top * scale).toInt(),
(bounds.width * scale).toInt(),
(bounds.height * scale).toInt(),
root.width,
root.height,
)
}
// 内容尺寸活值优先（0.14.10 issue ① 修复）：虚拟屏可随内容旋转，建屏快照只代表建屏瞬间；
// 活值来自 Display.getRealMetrics，异常/非法回退快照（VdisplayController.liveOrSnapshotSize）。
// 无屏/非法时按舞台比例兜底 = 满舞台（与既有 content==null 兜底一致）。
val content = VdisplayController.contentSizeForAlias(bounds.target)
val frame = if (content != null && content.first > 0 && content.second > 0) {
VdisplayLetterbox.containFrame(stage, content.first, content.second)
} else {
stage
}
// ── 几何落盘守卫（双守卫之一）────────────────────────────────────────────
// 四元组（width/height/leftMargin/topMargin）全等则跳过 setLayoutParams，断根
// 「每帧无条件 requestLayout -> onLayoutChange -> applyStageBounds」的自激供能腿之一。
val lp = surface.layoutParams
val geometryUnchanged = lp is FrameLayout.LayoutParams &&
lp.width == frame.width && lp.height == frame.height &&
lp.leftMargin == frame.left && lp.topMargin == frame.top
if (!geometryUnchanged) {
surface.layoutParams = FrameLayout.LayoutParams(frame.width, frame.height).apply {
leftMargin = frame.left
topMargin = frame.top
}
}
// Make the SurfaceView visible so its Surface is created; binding/arbitration happens in
// surfaceCreated. An occupied target is hidden again by bindSurface with a structured reason
// and per-frame retries are throttled behind the frozen-state guard above (30s per attempt;
// onDisplayAdded unfreezes immediately).
stageVisible = true
if (surface.visibility != View.VISIBLE) surface.visibility = View.VISIBLE
// D5（0.14.11）：屏被销毁 / 空闲回收 / 强制销毁时 controller 的 records 被清掉，而宿主的
// attached 只在 releaseViewerSurface / surfaceDestroyed 复位 ⇒ 这条 if (!attached) 永远不成立，
// 重建出来的屏再也挂不上（侧栏永久停在旧帧，用户只能收起/展开侧栏或切前后台）。
// 每帧读一次真源（只读、幂等）：本 viewer 已不再持有任何 Surface 时先把 attached 归零。
if (attached && !VdisplayController.holdsViewerSurface(viewerId)) attached = false
if (!attached) surface.holder.surface?.takeIf { it.isValid }?.let { bindSurface(it) }
updateFullscreenButton(frame)
}

private fun ensureEngine(epoch: ServiceEpoch) {
if (!isEpochCurrent(epoch)) return
val ownership = ShizukuTransport.prepareStartupOwnership(applicationContext)
if (!isEpochCurrent(epoch)) return
if (startupOwnershipPending(ownership.optString("reason"))) {
val delay = epoch.ownershipRetry.nextDelayMs() ?: SLOW_OWNERSHIP_RECHECK_MS
scheduleStartup(epoch, delay)
if (delay == SLOW_OWNERSHIP_RECHECK_MS) {
Log.i("dsh-root", "service startup remains deferred; ownership recheck in " + delay + "ms")
}
return
}
if (!ownership.optBoolean("ok")) LogCollector.log("dsh-root", "service preboot ownership repair incomplete: " + ownership.optString("reason"))
if (!isEpochCurrent(epoch)) return
val ready = engineManager.engineReady
if (!isEpochCurrent(epoch)) return
if (!ready) { epoch.startupQueued.set(false); return }
// FX-210.1：恢复入口是「服务路径与 Activity 路径」的共同前置——引擎已被前台服务拉起
// 时重开 app 也要消费 .snapshot-transaction 判据（此前只在 Activity 启动流内、且在
// 「引擎已在跑」早退之后）。幂等：无事务时只是一次 stat。
engineManager.recoverInterruptedRefresh()
// Recovery can wait in root/Binder/disk; never install after that wait without a new epoch check.
if (!isEpochCurrent(epoch)) return
if (engineManager.snapshotRecoveryBlocksRuntime()) {
Log.e("dsh-engine", "startup held: snapshot recovery journal remains unresolved")
epoch.startupQueued.set(false)
return
}
// §6.2：启动窗口本身算活动（口径三类之一）——先记租约再取锁，否则租约空时取到的锁
// 下一拍就会被放掉，等于没取。
noteWakeActivity()
WatchdogV2.acquireWakeLock(this, epoch.wakeOwner)
if (!isEpochCurrent(epoch)) { WatchdogV2.releaseWakeLock(epoch.wakeOwner); return }
val exec = Executors.newSingleThreadScheduledExecutor()
if (!epoch.watchdog.compareAndSet(null, exec)) { exec.shutdownNow(); return }
if (!isEpochCurrent(epoch)) { retireEpoch(epoch); return }
try {
// §6.3：把第一拍挂上调度链（此后每拍由 watchdogTick 自己按状态重排）。
scheduleWatchdogTick(epoch, exec, WatchdogV2.HEALTHY_TICK_MS)
} catch (t: Throwable) {
retireEpoch(epoch)
if (!serviceDestroyed && !userShutdown) Log.e("dsh-watchdog", "watchdog installation failed", t)
}
if (!isEpochCurrent(epoch)) retireEpoch(epoch)
}

