val missing = denyMars.filterValues { !center.contains(it) }.keys
assertTrue("拒因记账串缺席（新增取值必须补记账）：" + missing.joinToString(","), missing.isEmpty())
val dupes = denyMars.values.groupBy { it }.filterValues { it.size > 1 }.keys
