export function nativeControlEndpoint(filesDir: unknown): string {
if (typeof filesDir !== 'string' || filesDir.length === 0 || filesDir.trim() !== filesDir) {
throw new PhoneControlBridgeError('files-dir-unavailable', 'DSH_FILES_DIR is not available')
}
if (!filesDir.startsWith('/') || filesDir.includes('\\')) {
throw new PhoneControlBridgeError('files-dir-invalid', 'DSH_FILES_DIR must be an absolute path')
}
// Android 路径是 POSIX 语义；Windows 上的 node:path.join 会产出反斜杠，必须显式拼接。
const endpoint = filesDir.replace(/\/+$/u, '') + '/' + NATIVE_CONTROL_SOCKET
try {
return assertNativeEndpoint(endpoint)
} catch (failure) {
throw new PhoneControlBridgeError(
'endpoint-invalid',
failure instanceof Error ? failure.message : 'native control endpoint is invalid',
)
}
}

export function createNativeClient(options: NativeClientOptions): NativeClient {
let endpoint: string
try {
endpoint = assertNativeEndpoint(options.endpoint)
} catch (failure) {
const message = failure instanceof Error ? failure.message : String(failure)
return invalidClient('endpoint-invalid', message)
}
const connector = options.connector ?? defaultConnector
return {
capabilities: (rpc = {}) =>
rpcCall(connector, endpoint, { method: 'capabilities' }, rpc),
execute: (request, rpc = {}) => {
const payload = executeRequest(request)
if ('error' in payload) return Promise.resolve(payload.error)
return rpcCall(connector, endpoint, payload.value, rpc)
},
cancel: (callId, rpc = {}) => {
if (!CALL_ID.test(callId)) return Promise.resolve(requestFailure('callId is invalid'))
return rpcCall(connector, endpoint, { method: 'cancel', callId }, rpc)
},
status: (callId, rpc = {}) => {
if (!CALL_ID.test(callId)) return Promise.resolve(requestFailure('callId is invalid'))
return rpcCall(connector, endpoint, { method: 'status', callId }, rpc)
},
}
}

