readyState: parseShizukuReadyState(parsed.readyState),
probeError: parseProbeError(parsed.functionalProbe),
guidance: typeof parsed.guidance === 'string' ? parsed.guidance : '',
}
} catch {
return SHIZUKU_UNREADABLE
}
}

